  "bools" = { {
      "name" = "udp4PanFewestMembers",
      "value" = true,
      "comment" = "---- the prose bools (the R789 wiring) ---- The gnomish pantheon is the demi-human pantheon with the fewest members",
    }, {
      "name" = "udp4PanGarlRulesAll",
      "value" = true,
      "comment" = "All gnomish gods except Urdlen the Crawler are ruled by Garl Glittergold",
    }, {
      "name" = "udp4PanGoldenHills",
      "value" = true,
      "comment" = "All but Urdlen live on the Twin Paradises in the Golden Hills, where the souls of faithful gnomes go at death",
    }, {
      "name" = "udp4PanUrdlenInAbyss",
      "value" = true,
      "comment" = "Urdlen lives in the Abyss",
    }, {
      "name" = "udp4PanAllMasculine",
      "value" = true,
      "comment" = "All the known gnomish deities are masculine, worshiped by male and female gnomes with equal reverence",
    }, {
      "name" = "udp4PanCleverSensible",
      "value" = true,
      "comment" = "They lack the he-man image and are clever, sensible, and helpful",
    }, {
      "name" = "udp4PanUrdlenSexless",
      "value" = true,
      "comment" = "Urdlen is sexless though still referred to as a he, and shares none of these good qualities",
    }, {
      "name" = "udp4PanCompanionsCommon",
      "value" = true,
      "comment" = "Gnomish gods nearly always have at least one companion - a weapon, animal, or other deity",
    }, {
      "name" = "udp4PanGarlHasArumdina",
      "value" = true,
      "comment" = "Garl has Arumdina, his intelligent battle axe",
    }, {
      "name" = "udp4PanSegojanGolemFriend",
      "value" = true,
      "comment" = "Segojan is sometimes accompanied by an intelligent stone golem",
    }, {
      "name" = "udp4PanUrdlenFriendless",
      "value" = true,
      "comment" = "Urdlen, an exception again, has no friends",
    }, {
      "name" = "udp4PanPranksAgainstEnemies",
      "value" = true,
      "comment" = "Pranks and practical jokes are a major response of gnomish gods to their enemies",
    }, {
      "name" = "udp4PanLooseDwarvenContact",
      "value" = true,
      "comment" = "They usually only associate with other gnomish deities, though they keep loose contact with a few dwarven gods",
    }, {
      "name" = "udp4PanMostActive",
      "value" = true,
      "comment" = "The gnomish pantheon is one of the most active and most involved with its worshipers",
    }, {
      "name" = "udp4BaeRivalOfGarl",
      "value" = true,
      "comment" = "He is Garl Glittergold closest rival in the field of good-natured mischief, slightly better at thieving practice",
    }, {
      "name" = "udp4BaeWoodBrownClothes",
      "value" = true,
      "comment" = "He dresses in clothes of wood-brown hues",
    }, {
      "name" = "udp4BaeOnlyHeApproachesTree",
      "value" = true,
      "comment" = "Only Baervan may safely approach Whisperleaf; the tree attacks all others as a treant of maximum size and hit points",
    }, {
      "name" = "udp4BaeTreeObeysOnlyHim",
      "value" = true,
      "comment" = "The animated tree/treant obeys all of Baervan orders and no one elses",
    }, {
      "name" = "udp4BaeChikHasty",
      "value" = true,
      "comment" = "Chiktikka is highly intelligent but prone to act before he thinks",
    }, {
      "name" = "udp4BaeChikBorrower",
      "value" = true,
      "comment" = "Many stories are told of the trouble Chiktikka starts by borrowing something valuable",
    }, {
      "name" = "udp4BaeNutBrownSkin",
      "value" = true,
      "comment" = "Baervan is distinguished by his nut-brown skin and pale gray hair",
    }, {
      "name" = "udp4BaeKeepsToHimself",
      "value" = true,
      "comment" = "He tends to keep to himself except for Chiktikka company, and sometimes roams the forests of the Prime Material Plane",
    }, {
      "name" = "udp4BaeGiftOncePerLifetime",
      "value" = true,
      "comment" = "Such a worshiper will meet Baervan only once in his or her lifetime",
    }, {
      "name" = "udp4BaeHardToDislike",
      "value" = true,
      "comment" = "Though he sometimes plays jokes on other creatures, it is hard not to like him",
    }, {
      "name" = "udp4BaeFollowersOutdoorsmen",
      "value" = true,
      "comment" = "Gnomish fighters, fighter/thieves, and thieves of a non-evil nature follow him, preferring the outdoors to a city",
    }, {
      "name" = "udp4UrdEvilImpulse",
      "value" = true,
      "comment" = "Urdlen is the epitome of the evil impulse that rules some gnomes and is feared by the rest",
    }, {
      "name" = "udp4UrdFurlessWhiteMole",
      "value" = true,
      "comment" = "He appears as a huge, dead-white, furless mole with claws of steel",
    }, {
      "name" = "udp4UrdLustsForMetals",
      "value" = true,
      "comment" = "He lusts for precious metals, jewels, and the blood of any human, humanoid, or demi-human",
    }, {
      "name" = "udp4UrdUnpredictable",
      "value" = true,
      "comment" = "No one can predict where he will strike next, or what his plans are to further evil among gnomekind",
    }, {
      "name" = "udp4UrdPermanentBlur",
      "value" = true,
      "comment" = "His form is distorted by a permanent blur spell which cannot be dispelled while he lives",
    }, {
      "name" = "udp4UrdEatsSlainClericSoul",
      "value" = true,
      "comment" = "If a protected cleric is slain anyway while the blur is in effect, Urdlen will eat the gnome soul when it reaches the Abyss",
    }, {
      "name" = "udp4UrdAppeasedByBlood",
      "value" = true,
      "comment" = "His clerics appease him by pouring the blood of a creature they have killed into the ground and burying it",
    }, {
      "name" = "udp4UrdSacrificeByRuining",
      "value" = true,
      "comment" = "Jewels and valuable metal goods are sacrificed by ruining them - breaking, tarnishing, melting - and then burying them",
    }, {
      "name" = "udp4UrdAtWarWithPantheon",
      "value" = true,
      "comment" = "Clerics of this deity are continually at war with the rest of the gnomish deities and their clerics and followers",
    }, {
      "name" = "udp4UrdFollowersUnderground",
      "value" = true,
      "comment" = "Gnomish assassins and evil thieves and fighters worship him, often living underground after the manner of his chaotic tunnel home",
    }, {
      "name" = "udp4SegSpeaksToRock",
      "value" = true,
      "comment" = "He is a friend to all living animals above and below the earth, and one who speaks to the very rock itself",
    }, {
      "name" = "udp4SegGraySkinned",
      "value" = true,
      "comment" = "He is known to his worshipers as a gray-skinned gnome",
    }, {
      "name" = "udp4SegGolemAverageIntelligence",
      "value" = true,
      "comment" = "The rod-created stone golem is of average intelligence and obeys Segojan commands alone",
    }, {
      "name" = "udp4SegGolemNeedsRockMass",
      "value" = true,
      "comment" = "The rod must be pressed against a mass of rock of sufficient size to form the golem",
    }, {
      "name" = "udp4SegLesserGodOfMagic",
      "value" = true,
      "comment" = "He is also seen in a lesser way as the gnomish god of magic",
    }, {
      "name" = "udp4SegIllusionistFollowers",
      "value" = true,
      "comment" = "Many of his followers are illusionists who strive to improve their art for the betterment of gnomekind",
    }, {
      "name" = "udp4SegMinersAndJewelers",
      "value" = true,
      "comment" = "Gnomish miners and jewelers also revere this deity",
    }, {
      "name" = "udp4SegGlowingGemSymbols",
      "value" = true,
      "comment" = "His clerics frequently cast light or continual light on large well-cut gems for use as holy symbols, causing them to glow from within",
    }, {
      "name" = "udp4FlaApronOnlyArmor",
      "value" = true,
      "comment" = "He wears only a leather apron for armor, enchanted to reduce by half all damage from heat and fire",
    }, {
      "name" = "udp4FlaMithrilSkin",
      "value" = true,
      "comment" = "His skin is the color of mithril steel, his eyes flaming coals, and his hair and beard a brilliant blue-silver",
    }, {
      "name" = "udp4FlaStrongestGnomishGod",
      "value" = true,
      "comment" = "He is one of the strongest of gnomish deities, perhaps the most so",
    }, {
      "name" = "udp4FlaForgedArumdina",
      "value" = true,
      "comment" = "It was Flandal who helped forge and enchant Arumdina, Garl Glittergold battle axe",
    }, {
      "name" = "udp4FlaTravelsSeekingOres",
      "value" = true,
      "comment" = "He is often found traveling with one or two other gnomish deities in search of new ores and veins of metal",
    }, {
      "name" = "udp4FlaRhondangSpeaksFire",
      "value" = true,
      "comment" = "Rhondang converses naturally with all beings who use fire or dwell in fiery locations - red dragons, chimerae, fire elementals",
    }, {
      "name" = "udp4FlaTalksBeforeAttacking",
      "value" = true,
      "comment" = "This does not make him friendly toward those beings, though he will be prone to talk first before attacking",
    }, {
      "name" = "udp4FlaRhondangDoubleVsCold",
      "value" = true,
      "comment" = "Rhondang does double damage to cold-using or cold-dwelling creatures",
    }, {
      "name" = "udp4FlaElementalsObedient",
      "value" = true,
      "comment" = "His fire elementals are quite friendly toward him and obey him in all respects, because he needs their services to help forge items",
    }, {
      "name" = "udp4FlaWorkshopOnTwinParadises",
      "value" = true,
      "comment" = "When not traveling he is found in his workshop on the Twin Paradises, planning or making a new magical weapon",
    }, {
      "name" = "udp4FlaSmithsFollowHim",
      "value" = true,
      "comment" = "He is a popular god among the gnomish smiths; a large number of fighter/clerics follow his worship in some areas",
    }, {
      "name" = "udp4FlaFlamingHammerSpell",
      "value" = true,
      "comment" = "Some of his clerics have developed or been granted a new spell that makes their war hammers burst into flame like a flame tongue long sword",
    } },
